// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.engineimport com.roshan.persona.cognitive.model.ClarificationQuestionimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.persona.core.PersonaProfileimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Clarification Engine (Module 7 v2 — Step 7.2, P0). * * Detects ambiguous user input and asks 1-2 clarifying questions BEFORE * planning. Top assistants (Claude, ChatGPT) always ask first — NOUS does too. * * ## When clarification is needed (per strategy v2 §"ClarificationEngine") * *  - "Plan a trip" → where? how long? → 2 questions. *  - "Plan a 3-day Goa trip under ₹15K" → clear → 0 questions. *  - "Compare phones" → which phones? budget? → 1-2 questions. *  - "What should I do?" → about what? → 1 question. * * ## Rules * *  - Max [CognitiveConfig.maxClarificationQuestions] questions (default 2). *  - Questions are persona-styled (Atlas: "Might I ask, sir — where to?"). *  - If the query has explicit details → no clarification needed. *  - Returns `null` when no clarification is needed. * * ## Ambiguity detection * * The engine uses two strategies: *  1. **Heuristic** — keyword-based detection of missing critical info *     (destination, duration, budget, comparison subjects). *  2. **LLM-based** — when heuristics are inconclusive, a quick LLM call *     ("Is this query ambiguous? What's missing?"). * * For v1, we use heuristics only (fast, free, no LLM call). The LLM * strategy is a future enhancement (v3). * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ClarificationEngine</a> */class ClarificationEngine(    private val config: CognitiveConfig = CognitiveConfig(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Check if [query] needs clarification.     *     * @param query the user's input.     * @param persona the active persona (for styled questions).     * @return list of 0-2 clarifying questions, or null if query is clear.     */    suspend fun checkClarification(        query: String,        persona: PersonaProfile,    ): List<ClarificationQuestion>? = withContext(dispatcher) {        val ambiguities = detectAmbiguities(query)        if (ambiguities.isEmpty()) return@withContext null        // Limit to max questions.        val limited = ambiguities.take(config.maxClarificationQuestions)        // Style each question per persona.        limited.map { ambiguity ->            styleQuestion(ambiguity, persona)        }    }    /**     * Detect ambiguities in [query] using heuristics.     *     * Returns a list of missing-info types (DESTINATION, DURATION, BUDGET,     * COMPARISON_SUBJECT, PURPOSE). Empty list = no ambiguity.     *     * Pure function — fully testable without LLM.     */    internal fun detectAmbiguities(query: String): List<AmbiguityType> {        val lower = query.lowercase().trim()        val ambiguities = mutableListOf<AmbiguityType>()        // ─── Trip / travel planning ─────────────────────────────────        val isTripQuery = TRIP_KEYWORDS.any { lower.contains(it) }        if (isTripQuery) {            // Check for destination.            if (!hasDestination(lower)) {                ambiguities.add(AmbiguityType.DESTINATION)            }            // Check for duration.            if (!hasDuration(lower)) {                ambiguities.add(AmbiguityType.DURATION)            }        }        // ─── Comparison queries ─────────────────────────────────────        val isComparison = COMPARISON_KEYWORDS.any { lower.contains(it) }        if (isComparison) {            // Check if two or more subjects are mentioned.            if (!hasComparisonSubjects(lower)) {                ambiguities.add(AmbiguityType.COMPARISON_SUBJECT)            }        }        // ─── "What should I do" — too vague ─────────────────────────        if (VAGUE_KEYWORDS.any { lower.contains(it) }) {            ambiguities.add(AmbiguityType.PURPOSE)        }        // ─── Purchase / buy — need product + budget ─────────────────        val isPurchase = PURCHASE_KEYWORDS.any { lower.contains(it) }        if (isPurchase) {            if (!hasProduct(lower)) {                ambiguities.add(AmbiguityType.PRODUCT)            }        }        return ambiguities.distinct()    }    /**     * Style a question for [persona].     *     * Atlas: "Might I ask, sir — where to?"     * Nova: "Ooh, where are we going?!"     * Onyx: "Destination?"     */    private fun styleQuestion(ambiguity: AmbiguityType, persona: PersonaProfile): ClarificationQuestion {        val baseQuestion = when (ambiguity) {            AmbiguityType.DESTINATION -> "Where would you like to go?"            AmbiguityType.DURATION -> "How many days?"            AmbiguityType.BUDGET -> "What's your budget?"            AmbiguityType.COMPARISON_SUBJECT -> "Which options are you comparing?"            AmbiguityType.PURPOSE -> "What's this about specifically?"            AmbiguityType.PRODUCT -> "What product are you looking for?"        }        val baseReasoning = when (ambiguity) {            AmbiguityType.DESTINATION -> "I need a destination to plan your trip."            AmbiguityType.DURATION -> "I need the duration to find suitable options."            AmbiguityType.BUDGET -> "I need a budget to filter options."            AmbiguityType.COMPARISON_SUBJECT -> "I need to know what to compare."            AmbiguityType.PURPOSE -> "I need more context to help you."            AmbiguityType.PRODUCT -> "I need to know what you want to buy."        }        // Persona-styled question.        val styledQuestion = when (persona.id) {            "atlas" -> "Might I ask, sir — $baseQuestion".replaceFirstChar { it.lowercase() }            "nova" -> baseQuestion.replace("?", "!")  // enthusiastic            "onyx" -> baseQuestion.substringBefore("?").trim() + "."  // terse            "sage" -> "Let me ask — $baseQuestion".replaceFirstChar { it.lowercase() }            "echo" -> baseQuestion.replace("would you", "do you")            "vanguard" -> baseQuestion.substringBefore("?").trim() + ". Confirm."            "aria" -> "Ooh, $baseQuestion".replaceFirstChar { it.lowercase() }            "wraith" -> baseQuestion.substringBefore("?").trim() + "."  // minimal            "zenith" -> baseQuestion            else -> baseQuestion        }        return ClarificationQuestion(            question = styledQuestion,            options = ambiguity.defaultOptions,            reasoning = baseReasoning,        )    }    // ─── Heuristic helpers ─────────────────────────────────────────────────    private fun hasDestination(query: String): Boolean {        // Check for common city/country names or "to [place]" pattern.        return DESTINATION_PATTERNS.any { it.containsMatchIn(query) } ||            DESTINATION_KEYWORDS.any { query.contains(it) }    }    private fun hasDuration(query: String): Boolean {        return DURATION_PATTERNS.any { it.containsMatchIn(query) }    }    private fun hasComparisonSubjects(query: String): Boolean {        // Check for "X vs Y" or "X or Y" pattern.        return VS_PATTERN.containsMatchIn(query) ||            query.split(" or ").size >= 2 ||            query.split(" vs ").size >= 2    }    private fun hasProduct(query: String): Boolean {        // Check for product keywords.        return PRODUCT_KEYWORDS.any { query.contains(it) }    }    // ─── Companion constants ───────────────────────────────────────────────    companion object {        private val TRIP_KEYWORDS = listOf("plan a trip", "plan trip", "travel", "vacation", "holiday", "go to")        private val COMPARISON_KEYWORDS = listOf("compare", "vs", "versus", "better", "which is best", "difference between")        private val VAGUE_KEYWORDS = listOf("what should i do", "help me", "i need advice", "suggest something")        private val PURCHASE_KEYWORDS = listOf("buy", "purchase", "should i get", "should i buy")        private val DESTINATION_KEYWORDS = listOf(            "goa", "mumbai", "delhi", "bangalore", "bengaluru", "pune", "chennai",            "kerala", "rajasthan", "himachal", "uttarakhand", "japan", "europe",            "usa", "uk", "dubai", "singapore", "thailand", "bali",        )        private val DESTINATION_PATTERNS = listOf(            Regex("\\bto\\s+\\w+"),  // "to Goa"            Regex("\\bin\\s+\\w+"),  // "in Goa"        )        private val DURATION_PATTERNS = listOf(            Regex("\\b\\d+\\s*day"),    // "3 days"            Regex("\\b\\d+\\s*night"),  // "2 nights"            Regex("\\b\\d+\\s*week"),   // "1 week"            Regex("\\bweekend\\b"),      // "weekend"        )        private val VS_PATTERN = Regex("\\bvs\\.?\\b|\\bversus\\b")        private val PRODUCT_KEYWORDS = listOf(            "phone", "laptop", "car", "tv", "headphone", "watch", "camera", "tablet",        )    }}// ──────────────────────────────────────────────────────────────────────────/** Types of ambiguity detected by [ClarificationEngine]. */enum class AmbiguityType(val displayLabel: String) {    DESTINATION("Missing Destination"),    DURATION("Missing Duration"),    BUDGET("Missing Budget"),    COMPARISON_SUBJECT("Missing Comparison Subjects"),    PURPOSE("Too Vague"),    PRODUCT("Missing Product");    /** Default multiple-choice options for this ambiguity (null = free-text). */    val defaultOptions: List<String>?        get() = when (this) {            DURATION -> listOf("1 day", "2 days", "3 days", "1 week")            BUDGET -> listOf("Budget-friendly", "Mid-range", "Premium")            else -> null  // free-text for destination, comparison, purpose, product        }}

